for f in ['accueil-velo.html','miam-ride-osm.html','introduction-miam-ride.html']:
    p='/mnt/user-data/outputs/'+f;s=open(p,encoding='utf-8').read()
    def rep(a,b):
        global s
        assert s.count(a)==1,(f,a[:70],s.count(a));s=s.replace(a,b)
    # overlay HTML
    rep('<div class="ov" id="qrp" hidden','<div class="ov" id="rev" hidden role="dialog" aria-label="Noter ce que tu as pris"><div class="sumh"><button class="ovx" id="rvx" type="button" aria-label="Fermer">×</button><h2>Ton avis</h2></div><div id="rvb"></div></div>\n  <div class="ov" id="qrp" hidden')
    # CSS
    rep('#qrp{z-index:50;','#rev{z-index:55;padding:14px 16px 28px}.rvq{margin:0 0 8px;font:800 20px/1.2 Poppins,sans-serif}.rvs{display:flex;gap:6px;margin:6px 0 2px}.rvs button{flex:1;border:2px solid var(--ink);border-radius:14px;background:#fff;color:var(--ink);padding:8px 0;font:800 20px/1 Poppins,sans-serif;cursor:pointer}.rvs button[aria-pressed="true"]{background:var(--yellow)}.rvl{margin:14px 0 6px;font-weight:600;font-size:13px}.rvok{text-align:center;padding:30px 0}.rvok b{display:block;font:800 22px Poppins,sans-serif;margin-bottom:6px}.lnk{border:0;background:none;color:var(--ink);font:700 12px Poppins,sans-serif;text-decoration:underline;cursor:pointer;padding:0 0 0 6px}.rvn{font-size:11.5px;color:var(--muted);margin:10px 0 0}#qrp{z-index:50;')
    # state + XP
    rep("const XPOF=()=>ME.km+claimedXP();","let REVS=(()=>{try{const a=JSON.parse(localStorage.getItem('mr_revs')||'[]');if(Array.isArray(a))return a}catch(e){}return[]})();\nconst saveRevs=()=>{try{localStorage.setItem('mr_revs',JSON.stringify(REVS.slice(-200)))}catch(e){}},REVXP=5,revXP=()=>REVXP*REVS.length;\nconst XPOF=()=>ME.km+claimedXP()+revXP();")
    # own review in product tag
    rep("const tags=b=>S.prod&&prodOf(b)?`<span class=\"pdl\">Propose : ${S.prod.toLowerCase()}</span>`:'';","const myRev=(n,p)=>REVS.slice().reverse().find(r=>r.b===n&&r.p===p);\nconst tags=b=>{if(!S.prod||!prodOf(b))return'';const m=myRev(b[0],S.prod);return `<span class=\"pdl\">Propose : ${S.prod.toLowerCase()}${m?` · ton avis : ${m.s}/5`:''}</span>`};")
    # qrDone: mark and open review
    rep("function qrDone(nx){REC.stops.push({n:nx.n,km:REC.km,i:REC.pts.length-1});","function qrDone(nx){REC.stops.push({n:nx.n,km:REC.km,i:REC.pts.length-1,rated:false});setTimeout(()=>revOpen(REC.stops.length-1),350);")
    rep("function recStopsUI(){const e=$('#rstops');if(e)e.innerHTML=REC.stops.length?'<small>Arrêts : </small>'+REC.stops.map(s=>`<small>${s.n} (km ${s.km.toFixed(1).replace('.',',')})</small>`).join('<br>'):''}","function recStopsUI(){const e=$('#rstops');if(!e)return;e.innerHTML=REC.stops.length?'<small>Arrêts : </small>'+REC.stops.map((s,i)=>`<small>${s.n} (km ${s.km.toFixed(1).replace('.',',')})${s.rated===false?`<button type=\"button\" class=\"lnk\" data-rv=\"${i}\">Noter</button>`:s.rated?' · noté ✓':''}</small>`).join('<br>'):'';e.querySelectorAll('[data-rv]').forEach(b=>b.onclick=()=>revOpen(+b.dataset.rv))}\nfunction revOpen(i){const st=REC.stops[i];if(!st||st.rated)return;const R=$('#rev'),B=$('#rvb');let prod=null,stars=0,more=false;\n const draw=()=>{const L=PRODS.concat(prod&&PRODX.includes(prod)?[prod]:[]);\n  B.innerHTML=`<p class=\"rvq\">Tu as pris quoi chez ${st.n} ?</p><div class=\"chips\" id=\"rvp\" style=\"flex-wrap:wrap\">${L.map(f=>`<button type=\"button\" data-f=\"${f}\" aria-pressed=\"${prod===f}\">${f}</button>`).join('')}<button type=\"button\" data-f=\"__x\" aria-pressed=\"${more}\">Autre…</button></div>${more?`<select id=\"rvx2\" aria-label=\"Autre produit\" style=\"margin-top:8px;font:600 13px Poppins,sans-serif;border:2px solid var(--ink);border-radius:99px;padding:5px 10px;background:#fff;color:var(--ink)\"><option value=\"\">Choisis un produit…</option>${PRODX.map(x=>`<option>${x}</option>`).join('')}</select>`:''}<p class=\"rvl\">Ta note</p><div class=\"rvs\" id=\"rvst\">${[1,2,3,4,5].map(n=>`<button type=\"button\" data-s=\"${n}\" aria-pressed=\"${stars===n}\" aria-label=\"${n} sur 5\">${n}</button>`).join('')}</div><div class=\"sybtn\"><button type=\"button\" id=\"rvlater\">Plus tard</button><button class=\"y\" type=\"button\" id=\"rvsend\" ${prod&&stars?'':'disabled'}>Envoyer · +${REVXP} XP</button></div><p class=\"rvn\">Ton avis compte parce que ton passage est validé ici. Il aide les autres cyclistes à trouver le meilleur ${prod?prod.toLowerCase():'produit'} du secteur.</p>`;\n  B.querySelectorAll('#rvp button').forEach(b=>b.onclick=()=>{const f=b.dataset.f;if(f==='__x')more=!more;else{prod=f;more=false}draw()});\n  if(more)$('#rvx2').onchange=e=>{if(e.target.value){prod=e.target.value;more=false;draw()}};\n  B.querySelectorAll('#rvst button').forEach(b=>b.onclick=()=>{stars=+b.dataset.s;draw()});\n  $('#rvlater').onclick=()=>{R.hidden=true};\n  $('#rvsend').onclick=()=>{REVS.push({b:st.n,p:prod,s:stars,d:todayIso()});saveRevs();st.rated=true;recStopsUI();revN();B.innerHTML=`<div class=\"rvok\"><b>Merci !</b>Ton avis sur ${prod.toLowerCase()} est enregistré. +${REVXP} XP.</div>`;setTimeout(()=>{R.hidden=true},1300)}};\n draw();R.hidden=false;$('#rvx').onclick=()=>{R.hidden=true}}\nfunction revN(){if($('#revN'))$('#revN').textContent=REVS.length}")
    # profile row
    rep('<div class="row"><span>Connecté en tant que</span><span class="v" id="acctMail">—</span></div>','<div class="row"><span>Connecté en tant que</span><span class="v" id="acctMail">—</span></div><div class="row"><span>Avis donnés</span><span class="v" id="revN">0</span></div>')
    rep("function acctUI(){const a=acct();","function acctUI(){revN();const a=acct();")
    open(p,'w',encoding='utf-8').write(s)
# espace
p='/mnt/user-data/outputs/espace-boulangerie.html';s=open(p,encoding='utf-8').read()
a='<div class="box"><h3 style="font-size:15px;margin-bottom:4px">Derniers passages</h3>'
assert s.count(a)==1
s=s.replace(a,'<div class="box"><h3 style="font-size:15px;margin-bottom:4px">Avis des cyclistes</h3><p class="sub" style="margin:0">Aucun avis pour l’instant. Après chaque passage validé chez toi, le cycliste peut dire ce qu’il a pris et le noter de 1 à 5. Tu verras ici les avis par produit.</p><p class="sub" style="margin:6px 0 0;font-size:12px">Un avis ne peut venir que d’un passage validé par QR dans ta boulangerie. Un produit n’est classé qu’à partir de plusieurs avis.</p></div>\n    '+a)
open(p,'w',encoding='utf-8').write(s)
